// HasKeluarga applies the HasEdge predicate on the "keluarga" edge.
func HasKeluarga() predicate.Umat {
	return predicate.Umat(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, KeluargaTable, KeluargaColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasKeluargaWith applies the HasEdge predicate on the "keluarga" edge with a given conditions (other predicates).
func HasKeluargaWith(preds ...predicate.Keluarga) predicate.Umat {
	return predicate.Umat(func(s *sql.Selector) {
		step := newKeluargaStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

