// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Umat) predicate.Umat {
	return predicate.Umat(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Umat) predicate.Umat {
	return predicate.Umat(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Umat) predicate.Umat {
	return predicate.Umat(sql.NotPredicates(p))
}
